-- Administrative verification only; fabricated users, sessions, documents and transactions.
-- Every change is rolled back. Never include household records or credentials here.
begin;
create temporary table planning_test_results(name text,passed boolean);
do $$
declare actor uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();otp uuid:=gen_random_uuid();person uuid;ret uuid;nextret uuid;item uuid;nextitem uuid;expense uuid;bank uuid;tx1 uuid;tx2 uuid;doc uuid;r jsonb;p jsonb;path text;source jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at,is_anonymous,created_at,updated_at) values(actor,'mock-planning-'||actor||'@example.invalid',now(),false,now(),now());
 insert into household_private.memberships(user_id,status,role) values(actor,'approved','member');insert into auth.sessions(id,user_id,aal) values(sid,actor,'aal1');
 insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values(gen_random_uuid(),sid,'passkey',now(),now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',sid,'role','authenticated')::text,true);
 r:=public.household_tax_v1('tax_create_workspace',jsonb_build_object('year',2098,'name','Mock tax person '||actor,'workstreams',jsonb_build_array('canada','us','fbar')));
 select id into person from household_private.tax_people where name='Mock tax person '||actor;
 select id into ret from household_private.tax_returns where year=2098 and person_id=person and workstream='canada';
 if (select count(*) from household_private.tax_returns where person_id=person)<>3 then raise exception 'Workstreams missing';end if;
 r:=public.household_tax_v1('tax_save_item',jsonb_build_object('year',2098,'return_id',ret,'title','Mock employment slip','status','reviewed','notes','Prior year only','due_date','2099-01-01'));item:=(r->>'id')::uuid;
 begin perform public.household_tax_v1('tax_save_item',jsonb_build_object('id',item,'revision',999,'year',2098,'return_id',ret,'title','Stale','status','missing'));raise exception 'Stale item saved';exception when serialization_failure then null;end;
 perform public.household_tax_v1('tax_create_workspace',jsonb_build_object('year',2099,'person_id',person,'workstreams',jsonb_build_array('canada'),'copy_from_year',2098));
 perform public.household_tax_v1('tax_create_workspace',jsonb_build_object('year',2099,'person_id',person,'workstreams',jsonb_build_array('canada'),'copy_from_year',2098));
 select id into nextret from household_private.tax_returns where year=2099 and person_id=person and workstream='canada';select id into nextitem from household_private.tax_items where return_id=nextret;
 if (select count(*) from household_private.tax_items where return_id=nextret)<>1 or (select status<>'missing' or notes<>'' or due_date is not null from household_private.tax_items where id=nextitem) then raise exception 'Annual reuse copied evidence/status or duplicated';end if;
 begin perform public.household_tax_v1('tax_save_item',jsonb_build_object('id',item,'revision',1,'year',2099,'return_id',nextret,'title','Cross year','status','missing'));raise exception 'Moved evidence across years';exception when invalid_parameter_value then null;end;
 insert into household_private.accounts(name,kind,currency) values('Mock tax bank '||actor,'checking','XTS') returning id into bank;
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint) values(bank,'2098-01-10','Mock tax purchase',-12000,'mock-tax-1-'||actor) returning id into tx1;
 insert into household_private.transactions(account_id,date,description,amount_minor,fingerprint) values(bank,'2098-01-11','Mock second purchase',-2000,'mock-tax-2-'||actor) returning id into tx2;
 select to_jsonb(t) into source from household_private.transactions t where id=tx1;
 p:=jsonb_build_object('year',2098,'return_id',ret,'purpose','Mock review only','receipt_required',true,'items',jsonb_build_array(jsonb_build_object('id',tx1,'revision',1),jsonb_build_object('id',tx2,'revision',99)));
 begin perform public.household_tax_v1('tax_flag_expenses',p);raise exception 'Stale bulk accepted';exception when serialization_failure then null;end;
 if exists(select 1 from household_private.tax_expenses where return_id=ret) then raise exception 'Partial tax bulk write';end if;
 p:=jsonb_set(p,'{items,1,revision}','1');r:=public.household_tax_v1('tax_flag_expenses',p);if r->>'created_count'<>'2' then raise exception 'Tax bulk did not flag both';end if;
 r:=public.household_tax_v1('tax_flag_expenses',p);if r->>'skipped_count'<>'2' then raise exception 'Repeated flags overwrote records';end if;
 if (select to_jsonb(t) from household_private.transactions t where id=tx1)<>source then raise exception 'Tax flag changed ledger';end if;
 select id into expense from household_private.tax_expenses where transaction_id=tx1 and return_id=ret;
 r:=public.household_tax_v1('tax_prepare_document',jsonb_build_object('year',2098,'target_kind','item','target_id',item,'filename','mock.pdf','mime_type','application/pdf','byte_size',12,'sha256',repeat('a',64)));doc:=(r->>'id')::uuid;path:=r->>'object_path';
 if not household_private.tax_document_permission(path,'upload') or household_private.tax_document_permission('unprepared/path','upload') then raise exception 'Prepared-path permission failed';end if;
 begin perform public.household_tax_v1('tax_finish_document',jsonb_build_object('id',doc,'revision',1));raise exception 'Missing object finished';exception when invalid_parameter_value then null;end;
 insert into storage.objects(bucket_id,name,metadata) values('household-tax-documents',path,'{"size":12,"mimetype":"application/pdf"}');
 r:=public.household_tax_v1('tax_finish_document',jsonb_build_object('id',doc,'revision',1));if r->>'state'<>'ready' or household_private.tax_document_permission(path,'upload') then raise exception 'Document finish/upload permission failed';end if;
 r:=public.household_tax_v1('tax_prepare_document',jsonb_build_object('year',2098,'target_kind','expense','target_id',expense,'filename','duplicate.pdf','mime_type','application/pdf','byte_size',12,'sha256',repeat('a',64)));
 if r->>'id'<>doc::text or r->>'already_exists'<>'true' then raise exception 'Document dedup/reuse failed';end if;
 perform public.household_tax_v1('tax_unlink_document',jsonb_build_object('target_kind','expense','target_id',expense,'document_id',doc));
 if not exists(select 1 from household_private.tax_document_links where document_id=doc and expense_id=expense and unlinked_at is not null) then raise exception 'Unlink lost history';end if;
 perform public.household_tax_v1('tax_link_document',jsonb_build_object('target_kind','expense','target_id',expense,'document_id',doc));
 begin perform public.household_tax_v1('tax_link_document',jsonb_build_object('target_kind','item','target_id',nextitem,'document_id',doc));raise exception 'Cross-year link allowed';exception when invalid_parameter_value then null;end;
 begin perform public.household_tax_v1('tax_prepare_document',jsonb_build_object('year',2098,'target_kind','item','target_id',item,'filename','../bad.pdf','mime_type','application/pdf','byte_size',12,'sha256',repeat('b',64)));raise exception 'Unsafe filename allowed';exception when invalid_parameter_value then null;end;
 r:=public.household_tax_v1('tax_get_workspace','{"year":2098}');
 if not exists(select 1 from jsonb_array_elements(r->'links') l where l->>'document_id'=doc::text and l->>'target_id'=expense::text) then raise exception 'Ready evidence missing';end if;
 perform public.household_tax_v1('tax_archive_expense',jsonb_build_object('id',expense,'revision',1,'archived',true));perform public.household_tax_v1('tax_archive_expense',jsonb_build_object('id',expense,'revision',2,'archived',false));
 if (select count(*) from household_private.tax_document_links where expense_id=expense and unlinked_at is null)<>1 then raise exception 'Archive lost evidence';end if;
 insert into planning_test_results values('tax years/workstreams, idempotent evidence-free copy, revisions, atomic flags and source preservation',true),('private document preparation, completion, dedup, same-year reuse and recoverable unlink/archive',true);
 insert into auth.sessions(id,user_id,aal) values(otp,actor,'aal1');insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values(gen_random_uuid(),otp,'otp',now(),now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',otp,'role','authenticated','amr',jsonb_build_array('passkey'))::text,true);
 begin perform public.household_tax_v1('tax_get_workspace','{"year":2098}');raise exception 'OTP read tax data';exception when insufficient_privilege then null;end;
 if household_private.tax_document_permission(path,'read') then raise exception 'OTP storage read allowed';end if;
 begin perform public.household_budget_v1('budget_get_workspace','{"month":"2026-08","currency":"XTS"}');raise exception 'OTP read budget';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',sid,'role','authenticated')::text,true);
 update household_private.memberships set status='removed' where user_id=actor;
 begin perform public.household_tax_v1('tax_get_workspace','{"year":2098}');raise exception 'Removed member read taxes';exception when insufficient_privilege then null;end;
 if household_private.tax_document_permission(path,'read') then raise exception 'Removed member downloaded document';end if;
 update household_private.memberships set status='approved' where user_id=actor;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',gen_random_uuid(),'role','authenticated')::text,true);
 begin perform public.household_budget_v1('budget_get_workspace','{"month":"2026-08","currency":"XTS"}');raise exception 'Missing session read budget';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'session_id',sid,'role','authenticated')::text,true);
 if has_table_privilege('authenticated','household_private.tax_documents','SELECT') or has_function_privilege('authenticated','household_private.tax_workspace(integer)','EXECUTE') or has_function_privilege('anon','public.household_tax_v1(text,jsonb)','EXECUTE') or has_table_privilege('authenticated','household_private.budget_lines','UPDATE') then raise exception 'Private tables/helpers or anonymous API exposed';end if;
 insert into planning_test_results values('stored passkey/session approval checks, OTP/spoofed AMR/revoked/missing-session denial and private grants',true);
end $$;
do $$
declare actor uuid:=auth.uid();bank uuid;expensecat uuid;incomecat uuid;purchase uuid;refund uuid;salary uuid;other uuid;r jsonb;p jsonb;report jsonb;plan uuid;link uuid;source jsonb;revision integer;value bigint;
begin
 insert into household_private.accounts(name,kind,currency) values('Mock budget bank '||actor,'checking','XTS') returning id into bank;
 insert into household_private.categories(name) values('Mock budget spending '||actor) returning id into expensecat;insert into household_private.categories(name) values('Mock budget income '||actor) returning id into incomecat;
 perform public.household_budget_v1('budget_create_month','{"month":"2026-08","currency":"XTS","refund_timing":"received","settings_revision":0,"copy_from":null}');
 perform public.household_budget_v1('budget_save_line',jsonb_build_object('month','2026-08','currency','XTS','plan_revision',1,'category_id',expensecat,'role','expense','planned_minor',20000,'rollover_mode','unused','cap_minor',30000));
 perform public.household_budget_v1('budget_save_line',jsonb_build_object('month','2026-08','currency','XTS','plan_revision',2,'category_id',incomecat,'role','income','planned_minor',100000,'rollover_mode','reset','cap_minor',null));
 perform public.household_budget_v1('budget_create_month','{"month":"2026-09","currency":"XTS","refund_timing":"received","settings_revision":1,"copy_from":"2026-08"}');
 insert into household_private.transactions(account_id,category_id,date,description,amount_minor,fingerprint) values(bank,expensecat,'2026-08-10','Mock purchase',-12000,'mock-budget-p-'||actor) returning id into purchase;
 insert into household_private.transactions(account_id,category_id,date,description,amount_minor,fingerprint) values(bank,incomecat,'2026-09-10','Mock partial refund',4000,'mock-budget-r-'||actor) returning id into refund;
 insert into household_private.transactions(account_id,category_id,date,description,amount_minor,fingerprint) values(bank,expensecat,'2026-09-11','Mock September purchase',-3000,'mock-budget-o-'||actor) returning id into other;
 insert into household_private.transactions(account_id,category_id,date,description,amount_minor,fingerprint) values(bank,incomecat,'2026-09-01','Mock salary',100000,'mock-budget-s-'||actor) returning id into salary;
 select to_jsonb(t) into source from household_private.transactions t where id=purchase;
 p:=jsonb_build_object('currency','XTS','purchase_id',purchase,'purchase_revision',1,'refund_id',refund,'refund_revision',1,'amount_minor',5000);
 begin perform public.household_budget_v1('budget_link_refund',p);raise exception 'Oversized refund allowed';exception when invalid_parameter_value then null;end;
 p:=jsonb_set(p,'{amount_minor}','4000');r:=public.household_budget_v1('budget_link_refund',p);link:=(r->>'id')::uuid;
 begin perform public.household_budget_v1('budget_link_refund',p);raise exception 'Duplicate pair allowed';exception when serialization_failure then null;end;
 if (select to_jsonb(t) from household_private.transactions t where id=purchase)<>source then raise exception 'Refund changed ledger source';end if;
 r:=public.household_budget_v1('budget_get_workspace','{"month":"2026-09","currency":"XTS"}');report:=r->'report';
 if report->'remaining_minor'<>'null'::jsonb or report->>'income_minor'<>'100000' or report->>'expense_minor'<>'-1000' then raise exception 'Unknown prior coverage, income/refund separation or received timing failed: %',report;end if;
 perform public.household_budget_v1('budget_confirm_coverage','{"month":"2026-08","currency":"XTS","plan_revision":3,"confirmed":true}');
 r:=public.household_budget_v1('budget_get_workspace','{"month":"2026-09","currency":"XTS"}');report:=r->'report';
 select (e->>'opening_minor')::bigint into value from jsonb_array_elements(report->'lines') e where e->>'category_id'=expensecat::text;
 if value<>8000 or report->>'remaining_minor'<>'29000' then raise exception 'Received timing/carry math failed';end if;
 perform public.household_budget_v1('budget_set_refund_timing','{"currency":"XTS","revision":1,"refund_timing":"purchase"}');
 r:=public.household_budget_v1('budget_get_workspace','{"month":"2026-09","currency":"XTS"}');report:=r->'report';
 select (e->>'opening_minor')::bigint into value from jsonb_array_elements(report->'lines') e where e->>'category_id'=expensecat::text;
 if value<>12000 or report->>'expense_minor'<>'3000' or report->>'remaining_minor'<>'29000' then raise exception 'Purchase timing/history recalculation failed';end if;
 r:=public.household_budget_v1('budget_category_activity',jsonb_build_object('month','2026-08','currency','XTS','category_id',expensecat,'offset',0,'limit',50));
 if r->>'total'<>'2' or not exists(select 1 from jsonb_array_elements(r->'rows') e where e->>'id'=refund::text and e->>'peer_id'=purchase::text and e->>'budget_impact_minor'='-4000') then raise exception 'Cross-month source drill-down lost refund peer';end if;
 begin perform public.household_budget_v1('budget_save_line',jsonb_build_object('month','2026-09','currency','XTS','plan_revision',999,'category_id',expensecat,'role','expense','planned_minor',1,'rollover_mode','reset','cap_minor',null));raise exception 'Stale plan write accepted';exception when serialization_failure then null;end;
 update household_private.transactions set deleted_at=now(),revision=transactions.revision+1 where id=purchase;
 r:=public.household_budget_v1('budget_get_workspace','{"month":"2026-09","currency":"XTS"}');
 if r->'report'->>'income_minor'<>'100000' or r->'report'->>'unallocated_credits_minor'<>'4000' or jsonb_array_length(r->'report'->'issues')<>1 then raise exception 'Broken refund silently became income';end if;
 update household_private.transactions set deleted_at=null,revision=transactions.revision+1 where id=purchase;
 perform public.household_budget_v1('budget_unlink_refund',jsonb_build_object('id',link,'revision',1));
 if not exists(select 1 from household_private.budget_refund_links where id=link and unlinked_at is not null) then raise exception 'Unlink lost refund history';end if;
 begin perform public.household_budget_v1('budget_create_month','{"month":"2026-07","currency":"XTS","settings_revision":2,"refund_timing":"purchase","copy_from":null}');raise exception 'Anchor moved without review';exception when invalid_parameter_value then null;end;
 perform public.household_budget_v1('budget_create_month','{"month":"2099-01","currency":"YTS","settings_revision":0,"refund_timing":"received","copy_from":null}');
 begin perform public.household_budget_v1('budget_confirm_coverage','{"month":"2099-01","currency":"YTS","plan_revision":1,"confirmed":true}');raise exception 'Future coverage confirmed';exception when invalid_parameter_value then null;end;
 if public.household_budget_v1('budget_get_workspace','{"month":"2099-01","currency":"YTS"}')->'report'->>'expense_minor'<>'0' then raise exception 'Currency spending leaked';end if;
 insert into household_private.accounts(name,kind,currency) values('Mock new coverage account '||actor,'savings','XTS');
 r:=public.household_budget_v1('budget_get_workspace','{"month":"2026-09","currency":"XTS"}');if r->'report'->'remaining_minor'<>'null'::jsonb then raise exception 'Account-scope change kept stale carry';end if;
 insert into planning_test_results values('exact partial refunds, duplicate/cap rejection, immutable sources, separate income/currency and soft unlink',true),('explicit refund timing, recomputed rollover, incomplete/gapped coverage and cross-month source drill-down',true);
end $$;
do $$
declare actor uuid:=auth.uid();category uuid;r jsonb;p jsonb;doc uuid;path text;target uuid;total integer;
begin
 select id into category from household_private.categories where name='Mock budget spending '||actor;
 perform public.household_budget_v1('budget_save_profile','{"revision":0,"adults":2,"children":1,"province":"Mock province","tenure":"owner","income_quintile":""}');
 begin perform public.household_budget_v1('budget_save_profile','{"revision":1,"adults":0}');raise exception 'Invalid profile accepted';exception when invalid_parameter_value then null;end;
 p:=jsonb_build_object('revision',0,'cohort_label','Canada · All quintiles','source_table','11-10-0223-01','reference_year',2023,'mappings',jsonb_build_array(jsonb_build_object('category_id',category,'source_table','11-10-0223-01','reference_year',2023,'expenditure_label','Food purchased from stores','comparable',true,'note','')));
 perform public.household_budget_v1('budget_save_benchmarks',p);
 r:=public.household_budget_v1('budget_get_workspace','{"month":"2026-09","currency":"XTS"}');
 if r->'mappings'->0?'enabled' then raise exception 'Internal mapping field leaked into edit payload';end if;
 p:=jsonb_set(jsonb_set(p,'{revision}','1'),'{mappings}',r->'mappings');perform public.household_budget_v1('budget_save_benchmarks',p);
 begin perform public.household_budget_v1('budget_save_benchmarks',jsonb_set(p,'{cohort_label}','"Invented occupation + city + family group"'));raise exception 'Stale comparison accepted';exception when serialization_failure then null;end;
 begin perform public.household_tax_v1('tax_get_workspace','{"year":2098,"sql":"Forbidden"}');raise exception 'Unknown fields accepted';exception when invalid_parameter_value then null;end;
 select i.id into target from household_private.tax_items i join household_private.tax_returns r on r.id=i.return_id join household_private.tax_people p on p.id=r.person_id where r.year=2098 and p.name='Mock tax person '||actor limit 1;
 r:=public.household_tax_v1('tax_prepare_document',jsonb_build_object('year',2098,'target_kind','item','target_id',target,'filename','mock-policy.pdf','mime_type','application/pdf','byte_size',12,'sha256',repeat('c',64)));doc:=(r->>'id')::uuid;path:=r->>'object_path';
 execute 'set local role authenticated';
 perform public.household_tax_v1('tax_get_workspace','{"year":2098}');
 begin perform count(*) from household_private.tax_documents;raise exception 'Authenticated role read private table';exception when insufficient_privilege then null;end;
 begin insert into storage.objects(bucket_id,name,metadata) values('household-tax-documents','not/prepared','{"size":12,"mimetype":"application/pdf"}');raise exception 'Arbitrary upload path passed RLS';exception when insufficient_privilege then null;end;
 insert into storage.objects(bucket_id,name,metadata) values('household-tax-documents',path,'{"size":12,"mimetype":"application/pdf"}');
 perform public.household_tax_v1('tax_finish_document',jsonb_build_object('id',doc,'revision',1));
 select count(*) into total from storage.objects where bucket_id='household-tax-documents' and name=path;if total<>1 then raise exception 'Approved authenticated document not readable';end if;
 execute 'reset role';
 insert into planning_test_results values('actual authenticated-role RLS, prepared upload paths and API-only table access',true),('private comparison profiles, published cohort mappings, revision retries and strict request fields',true);
end $$;
select * from planning_test_results order by name;
rollback;
